  .argument('<task>', 'Standardized task number')
  .option('--mode <mode>', 'Execution mode', 'baseline')
  .option('--no-gate', 'Bypass summarizer gate')
  .action(async (task, options) => {
    if (!options.noGate) {
      const summarizer = new Summarizer();
      const summary = await summarizer.generate({ mode: options.mode });
      console.log('Gate Summary:', JSON.stringify(summary, null, 2));
      // Proceed only if summary valid (e.g., totalTasks > 0)
      if (summary.totalTasks === 0) throw new Error('No history for flagship execution');
    }
    console.log(`Running task ${task} in ${options.mode} mode`);
    // Flagship logic here
  });
```

